mapper.select:
SELECT 
FROM mp_subscription
WHERE publication_id = #{publicationId}
  AND tenant_company_id = #{tenantCompanyId}
  AND user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE mp_subscription
status = #{status}, end_time = #{endTime}, update_by = #{updateBy}, update_time = NOW(3)
WHERE id = #{id}
